import React from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';

const Home = () => {
    const navigate = useNavigate();
    const role = sessionStorage.getItem('accessRole');

    const goToAdmin = () => navigate('/admin');
    const goToEvaluation = () => navigate('/evaluation-simultaneous');

    return (
        <div className="home-container">
            <div className="welcome-box">
                <h2>Bienvenue</h2>
                <p>Veuillez sélectionner votre destination.</p>
                <div className="navigation-buttons">
                    {role === 'admin' && (
                        <button onClick={goToAdmin} className="nav-btn admin-btn">
                            Espace Administrateur
                        </button>
                    )}
                    {role === 'jury' && (
                        <button onClick={goToEvaluation} className="nav-btn jury-btn">
                            Commencer l'évaluation
                        </button>
                    )}
                     {role === 'admin' && (
                        <button onClick={goToEvaluation} className="nav-btn jury-btn">
                            Commencer l'évaluation
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Home;
